struct Visitor { virtual ~Visitor() = default; };          // degenerate, polymorphic
struct CircleVisitor { virtual void visit(Circle&) = 0; };

void Circle::accept(Visitor& v) {
    if (auto* cv = dynamic_cast<CircleVisitor*>(&v)) cv->visit(*this);
    else report_unhandled(*this, v);                      // cast failed == not supported
}

struct AreaVisitor : Visitor, CircleVisitor {             // only the interfaces it handles
    void visit(Circle& c) override { total += pi * c.r * c.r; }
};
